"    \".jpg\": \"image/jpeg\", \".jpeg\": \"image/jpeg\", \".gif\": \"image/gif\", \".webp\": \"image/webp\",\n"
"    \".avif\": \"image/avif\", \".ico\": \"image/x-icon\", \".woff2\": \"font/woff2\", \".woff\": \"font/woff\",\n"
"    \".ttf\": \"font/ttf\", \".mp4\": \"video/mp4\", \".webm\": \"video/webm\", \".mp3\": \"audio/mpeg\",\n"
"    \".pdf\": \"application/pdf\", \".wasm\": \"application/wasm\",\n"
"}\n"
"\n"
"# /static/<file> from the project's static/ folder.\n"
"fn __static(fd, path):\n"
"    rel = path[8:]\n"
"    parts = rel.split(\"/\")\n"
"    if rel == \"\" or \"..\" in parts or \"\" in parts or rel.startswith(\".\"):\n"
"        return respond(fd, 404, \"not found\", \"text/plain\")\n"
"    file = __root() + \"static/\" + rel\n"
"    if not __exists(file) or __isdir(file):\n"
"        return respond(fd, 404, \"not found\", \"text/plain\")\n"
"    dot = rel.rfind(\".\")\n"
"    ext = rel[dot:].lower() if dot >= 0 else \"\"\n"
"    return respond(fd, 200, __read_file(file), __TYPES.get(ext, \"application/octet-stream\"))\n"
"\n"
"# ------------------------------------------------------------------ dev\n"
"\n"
"# --dev: watch the project's .my and static files; on a change, check the\n"
"# changed scripts compile, then restart the app in place (the browser\n"
"# notices the new boot id and reloads).\n"
"fn __project_files(dir, out):\n"
"    for name in __listdir(dir):\n"
"        if name.startswith(\".\") or name == \"__mycache__\" or name == \"node_modules\":\n"
"            continue\n"
"        full = dir + name\n"
"        if __isdir(full):\n"
"            __project_files(full + \"/\", out)\n"
"        elif name.endswith(\".my\") or full.startswith(__root() + \"static/\"):\n"
"            out.append(full)\n"
"\n"
"fn __snapshot():\n"
"    files = []\n"
"    __project_files(__root(), files)\n"
"    return {f: __mtime(f) for f in files}\n"
"\n"
"fn __dev_check(close_all):\n"
"    now = monotonic()\n"
"    if now - __ui.get(\"dev_at\", 0) < 0.4:\n"
"        return Nil\n"
"    __ui[\"dev_at\"] = now\n"
"    snap = __snapshot()\n"
"    old = __ui.get(\"dev_snap\")\n"
"    __ui[\"dev_snap\"] = snap\n"
"    if old == Nil or snap == old:\n"
"        return Nil\n"
"    changed = [f for f in snap if old.get(f) != snap[f]] + [f for f in old if f not in snap]\n"
"    for f in changed:\n"
"        if f.endswith(\".my\") and __exists(f):\n"
"            try:\n"
"                compile(__read_file(f))\n"
"            catch:\n"
"                print(\"  ✗ \" + f + \" has an error; keeping the running version\")\n"
"                toast(\"Error in \" + f + \" (see the terminal)\", \"error\")\n"
"                __ui[\"version\"] += 1\n"
"                return Nil\n"
"    print(\"  ↻ \" + \", \".join([c.replace(__root(), \"\") for c in changed]) + \" changed, reloading\")\n"
"    close_all()\n"
"    setenv(\"MYMO_UI_RELOADED\", \"1\")\n"
"    __exec(args)\n"
"\n"
"\n"
"from \"server\" use listen, accept_nb, read_request, respond, close as __close\n"
"from \"runloop\" use nonblock, ready\n"
"\n"
"fn __path_only(p):\n"
"    i = p.find(\"?\")\n"
"    return p if i < 0 else p[:i]\n"
"\n"
"fn __query_key(p):\n"
"    i = p.find(\"k=\")\n"
"    if i < 0:\n"
"        return Nil\n"
"    k = p[i + 2:]\n"
"    j = k.find(\"&\")\n"
"    return k if j < 0 else k[:j]\n"
"\n"
"__LOCKED = `<!doctype html><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><body style=\"font:16px system-ui;padding:32px\"><script>var k=null;try{k=localStorage.getItem('mymo-k')}catch(e){}if(k)location.replace(location.pathname+'?k='+k);else document.body.textContent='Open the link shown in the terminal to use this app.'</script>`\n"
"\n"
"# Answer one HTTP request. Returns True when the connection stays open.\n"
"fn __serve_request(req):\n"
"    fd = req[\"client_fd\"]\n"
"    method = req[\"method\"]\n"
"    full = req[\"path\"]\n"
"    path = __path_only(full)\n"
"    __ui[\"seen\"] = monotonic()\n"
"    if path == \"/__ui/icon.svg\" or path == \"/favicon.ico\":\n"
"        return respond(fd, 200, __icon_svg(), \"image/svg+xml\")\n"
"    if path == \"/__ui/manifest.webmanifest\":\n"
"        return respond(fd, 200, __manifest(), \"application/manifest+json\")\n"
"    if path.startswith(\"/static/\"):\n"
"        return __static(fd, path)\n"
"    if method == \"POST\" and path.startswith(\"/__ui/\"):\n"
"        body = {}\n"
"        try:\n"
"            body = decode(req[\"body\"])\n"
"        catch:\n"
"            body = {}\n"
"        if __ui[\"key\"] != Nil and body.get(\"k\") != __ui[\"key\"]:\n"
"            return respond(fd, 403, \"{}\", \"application/json\")\n"
"        if path == \"/__ui/bye\":\n"
"            __ui[\"bye\"] = monotonic()\n"
"            return respond(fd, 204, \"\", \"text/plain\")\n"
"        __ui[\"bye\"] = Nil\n"
"        at = __path_only(str(body.get(\"path\", \"/\")))\n"
"        if path == \"/__ui/event\":\n"
"            __handle(at, body.get(\"id\"), body.get(\"values\"), body.get(\"v\"))\n"
"            return respond(fd, 200, encode(__reply(at)), \"application/json\")\n"
"        if path == \"/__ui/render\":\n"
"            return respond(fd, 200, encode(__reply(at)), \"application/json\")\n"
"        if path == \"/__ui/wait\":\n"
"            # Long poll: answer as soon as the view changes (see __flush).\n"
"            # A page from before a --dev restart gets the new boot id and reloads.\n"
"            if body.get(\"v\") != __ui[\"version\"] or len(__ui[\"toasts\"]) > 0 or body.get(\"boot\") != __ui[\"boot\"]:\n"
"                return respond(fd, 200, encode(__reply(at)), \"application/json\")\n"
"            __ui[\"parked\"].append({\"fd\": fd, \"path\": at, \"since\": monotonic()})\n"
"            return \"park\"\n"
"        return respond(fd, 404, \"{}\", \"application/json\")\n"
"    if __ui[\"key\"] != Nil and __query_key(full) != __ui[\"key\"]:\n"
"        return respond(fd, 403, __LOCKED, \"text/html; charset=utf-8\")\n"
"    __ui[\"bye\"] = Nil\n"
"    status = 200 if __find_page(path) != Nil else 404\n"
"    return respond(fd, status, __document(path), \"text/html; charset=utf-8\")\n"
"\n"
"fn __listen(host, port):\n"
"    last = Nil\n"
"    for p in range(port, port + 20):\n"
"        try:\n"
"            return (listen(host, p, 64), p)\n"
"        catch e:\n"
"            last = e\n"
"    raise last\n"
"\n"
"# Answer parked long polls: with the new view once the version moved\n"
"# (each page rendered once), with {} after 25 s. Returns the fds that\n"
"# stay open.\n"
"fn __flush(force=False):\n"
"    kept = []\n"
"    if len(__ui[\"parked\"]) == 0:\n"
"        return kept\n"
"    changed = __ui[\"version\"] != __ui.get(\"flushed\") or len(__ui[\"toasts\"]) > 0\n"
"    now = monotonic()\n"
"    views = {}\n"
"    still = []\n"
"    for pk in __ui[\"parked\"]:\n"
"        body = Nil\n"
"        if changed:\n"
"            if pk[\"path\"] not in views:\n"
"                views[pk[\"path\"]] = encode(__reply(pk[\"path\"]))\n"
"            body = views[pk[\"path\"]]\n"
"        elif force or now - pk[\"since\"] > 25:\n"
"            body = \"{}\"\n"
"        if body == Nil:\n"
"            still.append(pk)\n"
"            continue\n"
"        try:\n"
"            if respond(pk[\"fd\"], 200, body, \"application/json\"):\n"
"                kept.append(pk[\"fd\"])\n"
"        catch:\n"
"            pass\n"
"    __ui[\"parked\"] = still\n"
"    __ui[\"flushed\"] = __ui[\"version\"]\n"
"    return kept\n"
"\n"
"fn __serve(host, port, on_ready):\n"
"    srv, p = __listen(host, port)\n"
"    nonblock(srv)\n"
"    __ui[\"port\"] = p\n"
"    __ui[\"seen\"] = monotonic()\n"
"    __ui[\"bye\"] = Nil\n"
"    __ui[\"flushed\"] = __ui[\"version\"]\n"
"    on_ready(p)\n"
"    open = {}\n"
"    while True:\n"
"        due = __next_due()\n"
"        wait = 1000 if due < 0 or due > 1 else int(due * 1000) + 1\n"
"        if __ui[\"dev\"] and wait > 400:\n"
"            wait = 400\n"
"        tasks = __pending_fds()\n"
"        fds = [srv] + list(open.keys()) + tasks\n"
"        got = ready(fds, wait)\n"
"        for fd in got:\n"
"            if fd == srv:\n"
"                client = accept_nb(srv)\n"
"                while client != Nil:\n"
"                    open[client] = monotonic()\n"
"                    client = accept_nb(srv)\n"
"                continue\n"
"            if fd not in open:\n"
"                continue # a task's fd: see __wake\n"
"            req = Nil\n"
"            try:\n"
"                req = read_request(fd)\n"
"            catch:\n"
"                req = Nil\n"
"            if req is False:\n"
"                continue\n"
"            open.delete(fd)\n"
"            if req == Nil:\n"
"                continue\n"
"            keep = False\n"
"            try:\n"
"                keep = __serve_request(req)\n"
"            catch e:\n"
"                print(\"ui: \" + str(e))\n"
"                try:\n"
"                    __close(fd)\n"
"                catch:\n"
"                    pass\n"
"            if keep is True:\n"
"                open[fd] = monotonic()\n"
"        # Background work that's ready, then push any change to parked polls.\n"
"        __wake([fd for fd in got if fd in tasks])\n"
"        for fd in __flush():\n"
"            open[fd] = monotonic()\n"
"        now = monotonic()\n"
"        for fd in list(open.keys()):\n"
"            if now - open[fd] > 30:\n"
"                open.delete(fd)\n"
"                __close(fd)\n"
"        # A desktop window that closed (and didn't just reload) ends the app.\n"
"        if __ui[\"target\"] == \"desktop\" and __ui[\"bye\"] != Nil and now - __ui[\"bye\"] > 2:\n"
"            print(\"window closed\")\n"
"            return Nil\n"
"        if __ui[\"dev\"]:\n"
"            fn close_all():\n"
"                for fd in list(open.keys()) + [pk[\"fd\"] for pk in __ui[\"parked\"]] + [srv]:\n"
"                    try:\n"
"                        __close(fd)\n"
"                    catch:\n"
"                        pass\n"
"            __dev_check(close_all)\n"
"\n"
"# ------------------------------------------------------------- launchers\n"
"\n"
"fn __sh_quote(s):\n"
"    return \"'\" + str(s).replace(\"'\", \"'\\\\''\") + \"'\"\n"
"\n"
"fn __has(cmd):\n"
"    return system(\"command -v \" + cmd + \" >/dev/null 2>&1\") == 0\n"
"\n"
"fn __open_browser(url):\n"
"    if platform == \"darwin\":\n"
"        system(\"open \" + __sh_quote(url))\n"
"    elif platform == \"windows\":\n"
"        system(\"start \\\"\\\" \\\"\" + url + \"\\\"\")\n"
"    else:\n"
"        system(\"xdg-open \" + __sh_quote(url) + \" >/dev/null 2>&1 &\")\n"
"\n"
"fn __profile_dir():\n"
"    if platform == \"windows\":\n"
"        base = getenv(\"LOCALAPPDATA\")\n"
"        return (base if base != Nil else \".\") + \"\\\\mymo\\\\ui-profile\"\n"
"    home = getenv(\"HOME\")\n"
"    return (home if home != Nil else \"/tmp\") + \"/.mymo/ui-profile\"\n"
"\n"
"# Open `url` as a desktop app window: a Chromium-based browser in app\n"
"# mode (no tabs or address bar). Falls back to a normal browser tab.\n"
"fn __open_window(url):\n"
"    if platform == \"windows\":\n"
"        system(\"start \\\"\\\" msedge --app=\\\"\" + url + \"\\\" --user-data-dir=\\\"\" + __profile_dir() + \"\\\" --window-size=1180,800 --no-first-run\")\n"
"        return True\n"
"    flags = \" --app=\" + __sh_quote(url) + \" --user-data-dir=\" + __sh_quote(__profile_dir()) + \" --window-size=1180,800 --no-first-run --no-default-browser-check\"\n"
"    if platform == \"darwin\":\n"
"        for app in [\"Google Chrome\", \"Microsoft Edge\", \"Brave Browser\", \"Chromium\", \"Arc\"]:\n"
"            if system(\"test -d \" + __sh_quote(\"/Applications/\" + app + \".app\")) == 0:\n"
"                system(\"open -na \" + __sh_quote(app) + \" --args\" + flags)\n"
"                return True\n"
"    else:\n"
"        for exe in [\"google-chrome\", \"google-chrome-stable\", \"chromium\", \"chromium-browser\", \"microsoft-edge\", \"brave-browser\"]:\n"
"            if __has(exe):\n"
"                system(exe + flags + \" >/dev/null 2>&1 &\")\n"
"                return True\n"
"    __open_browser(url)\n"
"    return False\n"
"\n"
"fn __lan_ip():\n"
"    ip = \"\"\n"
"    try:\n"
"        if platform == \"darwin\":\n"
"            ip = popen(\"ipconfig getifaddr en0 2>/dev/null || ipconfig getifaddr en1 2>/dev/null\").strip()\n"
"        elif platform == \"linux\":\n"
"            parts = popen(\"hostname -I 2>/dev/null\").split()\n"
"            ip = parts[0] if len(parts) > 0 else \"\"\n"
"    catch:\n"
"        ip = \"\"\n"
"    return ip if ip != \"\" else \"localhost\"\n"
"\n"
"fn __token():\n"
"    t = \"\"\n"
"    if platform != \"windows\":\n"
"        try:\n"
"            t = popen(\"head -c 12 /dev/urandom | od -An -tx1 | tr -d ' \\\\n'\").strip()\n"
"        catch:\n"
"            t = \"\"\n"
"    if len(t) < 16:\n"
"        t = str(int(monotonic() * 1000003) % 999999937)\n"
"    return t\n"
"\n"
"# ------------------------------------------------------------------- run\n"
"\n"
"__HELP = `usage: mymo app.my [--desktop | --phone | --term | --browser] [--port N]\n"
"  (default)   open in your browser\n"
"  --desktop   open in its own window (Chrome, Edge or Brave in app mode)\n"
"  --phone     serve on your Wi-Fi; open the printed link on your phone\n"
"  --term      run full-screen in this terminal\n"
"  --serve     just serve on localhost (open it yourself)\n"
"  --dev       reload the app when you save a file (add to any of the above)\n"
"  --html      print the page's HTML and exit\n"
"  --text      print the terminal rendering and exit`\n"
"\n"
"# Start the app. `title`, `accent` (a CSS color) and `theme` (\"auto\",\n"
"# \"light\", \"dark\") style it; `view` registers a single-page app without\n"
"# @page. The target comes from the command line (see __HELP) unless\n"
"# `target` is given.\n"
"fn run(title=Nil, view=Nil, accent=Nil, theme=Nil, port=8765, target=Nil):\n"
"    if title != Nil:\n"
"        __ui[\"title\"] = str(title)\n"
"    if accent != Nil:\n"
"        __ui[\"accent\"] = accent\n"
"    if theme != Nil:\n"
"        __ui[\"theme\"] = theme\n"
"    if view != Nil:\n"
"        page(\"/\", view)\n"
"    if len(__ui[\"order\"]) == 0:\n"
"        raise RuntimeError(\"ui.run(): no pages; decorate a view with @page(\\\"/\\\") or pass view=\")\n"
"    if \"/\" not in __ui[\"pages\"]:\n"
"        __ui[\"pages\"][\"/\"] = __ui[\"pages\"][__ui[\"order\"][0]]\n"
"    flags = args[1:]\n"
"    if \"--help\" in flags or \"-h\" in flags:\n"
"        print(__HELP)\n"
"        return Nil\n"
"    for i in range(len(flags) - 1):\n"
"        if flags[i] == \"--port\":\n"
"            port = int(flags[i + 1])\n"
"    if target == Nil:\n"
"        target = \"browser\"\n"
"        for f in [\"desktop\", \"phone\", \"term\", \"html\", \"text\", \"serve\"]:\n"
"            if \"--\" + f in flags:\n"
"                target = f\n"
"    __ui[\"target\"] = target\n"
"    __ui[\"dev\"] = \"--dev\" in flags\n"
"    __ui[\"boot\"] = str(monotonic())\n"
"    reloaded = getenv(\"MYMO_UI_RELOADED\") == \"1\"\n"
"    if target == \"html\":\n"
"        print(__document(\"/\"))\n"
"        return Nil\n"
"    if target == \"text\":\n"
"        print(render_text(\"/\"))\n"
"        return Nil\n"
"    if target == \"term\":\n"
"        return __term_run()\n"
"    host = \"127.0.0.1\"\n"
"    if target == \"phone\":\n"
"        host = \"0.0.0.0\"\n"
"        __ui[\"key\"] = __token()\n"
"    fn ready_(p):\n"
"        url = \"http://127.0.0.1:\" + str(p) + \"/\"\n"
"        if reloaded:\n"
"            return Nil # dev restart: the open window reloads itself\n"
"        if target == \"phone\":\n"
"            url = \"http://\" + __lan_ip() + \":\" + str(p) + \"/?k=\" + __ui[\"key\"]\n"
"            print(\"\")\n"
"            print(\"  \" + __ui[\"title\"] + \" is running on your network.\")\n"
"            print(\"\")\n"
"            print(\"  Open on your phone (same Wi-Fi):  \" + url)\n"
"            print(\"  Then Share -> Add to Home Screen to install it as an app.\")\n"
"            print(\"  Anyone with this link on your network can use the app.\")\n"
"            print(\"\")\n"
"        elif target == \"desktop\":\n"
"            print(__ui[\"title\"] + \" -> \" + url + \" (opening a window; close it to quit)\")\n"
"            __open_window(url)\n"
"        else:\n"
"            print(__ui[\"title\"] + \" -> \" + url + \"  (Ctrl-C to stop\" + (\", reloads on save)\" if __ui[\"dev\"] else \")\"))\n"
"            if target == \"browser\":\n"
"                __open_browser(url)\n"
"    __serve(host, port, ready_)\n"
"\n"
"# ------------------------------------------------------------- terminal\n"
"\n"
"from \"term\" use isatty, size as __tsize, raw as __traw, key as __tkey, write as __twrite\n"
"from \"runloop\" use ready as __tready\n"
"\n"
"# Styles are ANSI SGR codes; in plain mode (render_text) they're dropped.\n"
"fn __sgr(codes, s):\n"
"    if __ui.get(\"plain\") or s == \"\":\n"
"        return s\n"
"    return \"\\x1b[\" + codes + \"m\" + s + \"\\x1b[0m\"\n"
"\n"
"fn __hex256(c):\n"
"    names = {\"accent\": __ui[\"accent\"], \"blue\": \"#3b82f6\", \"green\": \"#16a34a\", \"red\": \"#e5484d\", \"amber\": \"#d97706\",\n"
"             \"violet\": \"#8b5cf6\", \"pink\": \"#ec4899\", \"teal\": \"#0d9488\", \"gray\": \"#71717a\", \"orange\": \"#ea580c\"}\n"
"    h = names.get(c, c)\n"
"    if typename(h) != \"str\" or not h.startswith(\"#\") or len(h) != 7:\n"
"        h = __ui[\"accent\"]\n"
"    try:\n"
"        r = int(h[1:3], 16)\n"
"        g = int(h[3:5], 16)\n"
"        b = int(h[5:7], 16)\n"
"    catch:\n"
"        return 99\n"
"    q = (v => 0 if v < 48 else 1 if v < 115 else (v - 35) // 40)\n"
"    return 16 + 36 * q(r) + 6 * q(g) + q(b)\n"
"\n"
"fn __fg(color, s, bold=False):\n"
"    return __sgr((\"1;\" if bold else \"\") + \"38;5;\" + str(__hex256(color)), s)\n"
"\n"
"fn __dim(s):\n"
"    return __sgr(\"2\", s)\n"
"\n"
"fn __bold(s):\n"
"    return __sgr(\"1\", s)\n"
"\n"
"# Terminal columns a character takes: 2 for East Asian wide characters\n"
"# and emoji, 0 for combining marks and variation selectors.\n"
"fn __cw(ch):\n"
"    c = ord(ch)\n"
"    if c < 0x300:\n"
"        return 1\n"
"    if c >= 0x300 and c < 0x370 or c == 0x200D or c >= 0xFE00 and c <= 0xFE0F:\n"
"        return 0\n"
"    if c >= 0x1100 and c <= 0x115F or c >= 0x2E80 and c <= 0xA4CF or c >= 0xAC00 and c <= 0xD7A3:\n"
"        return 2\n"
"    if c >= 0xF900 and c <= 0xFAFF or c >= 0xFF00 and c <= 0xFF60 or c >= 0xFFE0 and c <= 0xFFE6:\n"
"        return 2\n"
"    if c >= 0x1F300 and c <= 0x1FAFF or c >= 0x20000 and c <= 0x3FFFD:\n"
"        return 2\n"
"    return 1\n"
"\n"
"# Visible width: terminal columns outside escape sequences (and not the\n"
"# focus marker \\x01).\n"
"fn __vlen(s):\n"
"    n = 0\n"
"    esc = False\n"
"    for ch in s:\n"
"        if esc:\n"
"            if ch == \"m\":\n"
"                esc = False\n"
"        elif ch == \"\\x1b\":\n"
"            esc = True\n"
"        elif ch != \"\\x01\":\n"
"            n += __cw(ch)\n"
"    return n\n"
"\n"
"fn __padr(s, w):\n"
"    n = __vlen(s)\n"
"    return s + \" \" * (w - n) if n < w else s\n"
"\n"
"# Cut to w visible columns, keeping escape sequences.\n"
"fn __cut(s, w):\n"
"    if __vlen(s) <= w:\n"
"        return s\n"
"    out = []\n"
"    n = 0\n"
"    esc = False\n"
"    for ch in s:\n"
"        if esc:\n"
"            out.append(ch)\n"
"            if ch == \"m\":\n"
"                esc = False\n"
"        elif ch == \"\\x1b\":\n"
"            esc = True\n"
"            out.append(ch)\n"
"        elif ch == \"\\x01\":\n"
"            out.append(ch)\n"
"        elif n + __cw(ch) <= w - 1:\n"
"            out.append(ch)\n"
"            n += __cw(ch)\n"
"        elif n < w:\n"
"            out.append(\"…\")\n"
"            n = w\n"
"    s = \"\".join(out)\n"
"    return s if __ui.get(\"plain\") else s + \"\\x1b[0m\"\n"
"\n"
"fn __wrap(text, w):\n"
"    if w < 1:\n"
"        w = 1\n"
"    lines = []\n"
"    for para in str(text).split(\"\\n\"):\n"
"        cur = \"\"\n"
"        for word in para.split(\" \"):\n"
"            while len(word) > w:\n"
"                if cur != \"\":\n"
"                    lines.append(cur)\n"
"                    cur = \"\"\n"
"                lines.append(word[:w])\n"
"                word = word[w:]\n"
"            if cur == \"\":\n"
"                cur = word\n"
"            elif len(cur) + 1 + len(word) <= w:\n"
"                cur += \" \" + word\n"
"            else:\n"
"                lines.append(cur)\n"
"                cur = word\n"
"        lines.append(cur)\n"
"    return lines\n"
"\n"
"fn __width(block):\n"
"    w = 0\n"
"    for l in block:\n"
"        n = __vlen(l)\n"
"        if n > w:\n"
"            w = n\n"
"    return w\n"
"\n"
"# Side by side, each block padded to its width.\n"
"fn __hjoin(blocks, widths, gap):\n"
"    h = 0\n"
"    for b in blocks:\n"
"        if len(b) > h:\n"
"            h = len(b)\n"
"    out = []\n"
"    for i in range(h):\n"
"        parts = []\n"
"        for j in range(len(blocks)):\n"
"            b = blocks[j]\n"
"            parts.append(__padr(b[i] if i < len(b) else \"\", widths[j]))\n"
"        out.append((\" \" * gap).join(parts).rstrip() if __ui.get(\"plain\") else (\" \" * gap).join(parts))\n"
"    return out\n"
"\n"
"__GLYPHS = {\n"
"    \"plus\": \"+\", \"minus\": \"−\", \"x\": \"✕\", \"check\": \"✓\", \"chevron-right\": \"›\", \"chevron-left\": \"‹\",\n"
"    \"chevron-down\": \"⌄\", \"chevron-up\": \"⌃\", \"arrow-right\": \"→\", \"arrow-left\": \"←\", \"search\": \"⌕\",\n"
"    \"home\": \"⌂\", \"user\": \"☺\", \"users\": \"☺\", \"settings\": \"≡\", \"trash\": \"✗\", \"edit\": \"✎\", \"star\": \"★\",\n"
"    \"heart\": \"♥\", \"bell\": \"♪\", \"mail\": \"✉\", \"calendar\": \"▦\", \"clock\": \"◷\", \"chart\": \"▥\",\n"
"    \"trend-up\": \"↗\", \"trend-down\": \"↘\", \"menu\": \"≡\", \"info\": \"ⓘ\", \"alert\": \"⚠\", \"check-circle\": \"✔\",\n"
"    \"sun\": \"☀\", \"moon\": \"☾\", \"folder\": \"▤\", \"file\": \"▢\", \"download\": \"↓\", \"upload\": \"↑\", \"logout\": \"⇥\",\n"
"    \"lock\": \"▣\", \"zap\": \"ϟ\", \"globe\": \"◍\", \"list\": \"≣\", \"grid\": \"⊞\", \"refresh\": \"↻\", \"inbox\": \"▭\",\n"
"    \"dollar\": \"$\", \"cart\": \"⊻\", \"send\": \"➤\", \"play\": \"▶\", \"pause\": \"‖\", \"eye\": \"◉\", \"sparkles\": \"✦\",\n"
"    \"filter\": \"⏷\", \"copy\": \"⧉\", \"external\": \"↗\", \"message\": \"✉\", \"book\": \"▯\", \"layers\": \"≋\", \"tag\": \"⌗\",\n"
"    \"map-pin\": \"⌖\", \"shield\": \"⛨\", \"terminal\": \"›\", \"code\": \"‹›\", \"image\": \"▣\", \"card\": \"▭\", \"box\": \"▢\",\n"
"    \"cloud\": \"☁\", \"cloud-sun\": \"☁\", \"cloud-rain\": \"☂\", \"cloud-snow\": \"❄\", \"cloud-lightning\": \"ϟ\",\n"
"    \"fog\": \"≡\", \"wind\": \"≈\", \"droplet\": \"∘\", \"thermometer\": \"°\",\n"
"}\n"
"\n"
"fn __glyph(name):\n"
"    return __GLYPHS.get(name, \"•\")\n"
"\n"
"# Blocky components get a blank line around them in a column.\n"
"__BLOCKY = [\"card\", \"section\", \"grid\", \"table\", \"alert\", \"stat\", \"empty\", \"row\", \"tabs\", \"progress\", \"kv\", \"navbar\"]\n"
"\n"
"fn __T_kids(kids, w, ctx, gap=Nil):\n"
"    out = []\n"
"    prev = Nil\n"
"    for k in kids:\n"
"        if k.t == \"modal\":\n"
"            __T_modal(k, w, ctx)\n"
"            continue\n"
"        b = __trender(k, w, ctx)\n"
"        if len(b) == 0:\n"
"            continue\n"
"        if prev != Nil and (gap != Nil and gap >= 5 or k.t in __BLOCKY or prev in __BLOCKY):\n"
"            out.append(\"\")\n"
"        out += b\n"
"        prev = k.t\n"
"    return out\n"
"\n"
"fn __trender(n, w, ctx):\n"
"    return __T[n.t](n, w, ctx)\n"
"\n"
"# Register a focusable element; returns whether it has the focus.\n"
"fn __tfocus(ctx, item):\n"
"    i = len(ctx[\"focus\"])\n"
"    ctx[\"focus\"].append(item)\n"
"    return i == __ui[\"tfocus\"]\n"
"\n"
"fn __mark(focused, s):\n"
"    return \"\\x01\" + s if focused and not __ui.get(\"plain\") else s\n"
"\n"
"fn __T_col(n, w, ctx):\n"
"    return __T_kids(n.kids, w, ctx, n.p.get(\"gap\"))\n"
"\n"
"fn __T_center(n, w, ctx):\n"
"    out = []\n"
"    for l in __T_kids(n.kids, w, ctx):\n"
"        pad = (w - __vlen(l)) // 2\n"
"        out.append(\" \" * (pad if pad > 0 else 0) + l)\n"
"    return out\n"
"\n"
"fn __T_row(n, w, ctx):\n"
"    kids = [k for k in n.kids if k.t != \"modal\"]\n"
"    for k in n.kids:\n"
"        if k.t == \"modal\":\n"
"            __T_modal(k, w, ctx)\n"
"    if len(kids) == 0:\n"
"        return []\n"
"    gap = 2\n"
"    real = [k for k in kids if k.t != \"spacer\"]\n"
"    spacers = len(kids) - len(real)\n"
"    # Cards, stats and the like fill whatever width they get: share it.\n"
"    blocky = len([k for k in real if k.t in [\"card\", \"stat\", \"grid\", \"table\", \"section\", \"progress\", \"input\", \"textarea\"]]) > 0\n"
"    # Natural widths: render once with the full width. Focus registration\n"
"    # must happen exactly once per element, so render into a scratch ctx\n"
"    # and replay the registrations with the final layout.\n"
"    avail = w - gap * (len(real) - 1)\n"
"    if not blocky:\n"
"        mark = len(ctx[\"focus\"])\n"
"        blocks = [__trender(k, avail, ctx) for k in real]\n"
"        widths = [__width(b) for b in blocks]\n"
"        total = sum(widths) + gap * (len(real) - 1)\n"
"        if total <= w:\n"
"            if spacers > 0 or n.p.get(\"justify\") == \"between\":\n"
"                # Push what follows the first spacer to the right edge.\n"
"                extra = w - total\n"
"                first = 0\n"
"                for k in kids:\n"
"                    if k.t == \"spacer\":\n"
"                        break\n"
"                    first += 1\n"
"                if spacers == 0:\n"
"                    first = 1\n"
"                left = blocks[:first]\n"
"                right = blocks[first:]\n"
"                lw = widths[:first]\n"
"                rw = widths[first:]\n"
"                lb = __hjoin(left, lw, gap) if len(left) > 0 else []\n"
"                rb = __hjoin(right, rw, gap) if len(right) > 0 else []\n"
"                lwid = sum(lw) + gap * (len(lw) - 1 if len(lw) > 0 else 0)\n"
"                return __hjoin([lb, rb], [lwid + extra, sum(rw) + gap * (len(rw) - 1 if len(rw) > 0 else 0)], gap if len(lb) > 0 and len(rb) > 0 else 0)\n"
"            return __hjoin(blocks, widths, gap)\n"
"        ctx[\"focus\"] = ctx[\"focus\"][:mark]\n"
"    share = avail // len(real)\n"
"    if share >= 16:\n"
"        blocks = [__trender(k, share, ctx) for k in real]\n"
"        return __hjoin(blocks, [share] * len(real), gap)\n"
"    return __T_kids(real, w, ctx)\n"
"\n"
"fn __T_grid(n, w, ctx):\n"
"    count = len(n.kids)\n"
"    if count == 0:\n"
"        return []\n"
"    cols = n.p[\"cols\"]\n"
"    if cols <= 0:\n"
"        minw = n.p[\"min\"] // 8 if typename(n.p[\"min\"]) == \"int\" else 28\n"
"        cols = w // (minw + 2)\n"
"    cols = 1 if cols < 1 else count if cols > count else cols\n"
"    share = (w - 2 * (cols - 1)) // cols\n"
"    out = []\n"
"    for i in range(0, count, cols):\n"
"        blocks = [__trender(k, share, ctx) for k in n.kids[i:i + cols]]\n"
"        if len(out) > 0:\n"
"            out.append(\"\")\n"
"        out += __hjoin(blocks, [share] * len(blocks), 2)\n"
"    return out\n"
"\n"
"fn __box(lines, w, title=Nil, color=Nil):\n"
"    inner = w - 4\n"
"    edge = (s => __fg(color, s)) if color != Nil else __dim\n"
"    top = \"╭\" + \"─\" * (w - 2) + \"╮\"\n"
"    if title != Nil:\n"
"        t = \" \" + __cut(str(title), w - 6) + \" \"\n"
"        top = edge(\"╭─\") + __bold(t) + edge(\"─\" * (w - 3 - __vlen(t)) + \"╮\")\n"
"    else:\n"
"        top = edge(top)\n"
"    out = [top]\n"
"    for l in lines:\n"
"        out.append(edge(\"│\") + \" \" + __padr(__cut(l, inner), inner) + \" \" + edge(\"│\"))\n"
"    out.append(edge(\"╰\" + \"─\" * (w - 2) + \"╯\"))\n"
"    return out\n"
"\n"
"fn __T_card(n, w, ctx):\n"
"    w = 12 if w < 12 else w\n"
"    body = []\n"
"    if n.p[\"subtitle\"] != Nil:\n"
"        body += [__dim(l) for l in __wrap(n.p[\"subtitle\"], w - 4)]\n"
"        body.append(\"\")\n"
"    body += __T_kids(n.kids, w - 4, ctx)\n"
"    return __box(body, w, n.p[\"title\"])\n"
"\n"
"fn __T_section(n, w, ctx):\n"
"    out = [__bold(n.p[\"title\"])]\n"
"    if n.p[\"subtitle\"] != Nil:\n"
"        out += [__dim(l) for l in __wrap(n.p[\"subtitle\"], w)]\n"
"    out.append(\"\")\n"
"    return out + __T_kids(n.kids, w, ctx)\n"
"\n"
"fn __T_spacer(n, w, ctx):\n"
"    return []\n"
"\n"
"fn __T_divider(n, w, ctx):\n"
"    if n.p[\"label\"] != Nil:\n"
"        l = \" \" + str(n.p[\"label\"]) + \" \"\n"
"        side = (w - len(l)) // 2\n"
"        return [__dim(\"─\" * side + l + \"─\" * (w - side - len(l)))]\n"
"    return [__dim(\"─\" * w)]\n"
"\n"
"fn __T_text(n, w, ctx):\n"
"    p = n.p\n"
"    lines = __wrap(p[\"text\"], w)\n"
"    out = []\n"
"    for l in lines:\n"
"        if p.get(\"color\") != Nil:\n"
"            l = __fg(p[\"color\"], l, p.get(\"bold\") or False)\n"
"        elif p.get(\"bold\") or p.get(\"size\") == \"xl\" or p.get(\"size\") == \"lg\":\n"
"            l = __bold(l)\n"
"        elif p.get(\"muted\"):\n"
"            l = __dim(l)\n"
"        if p.get(\"center\"):\n"
"            l = \" \" * ((w - __vlen(l)) // 2) + l\n"
"        out.append(l)\n"
"    return out\n"
"\n"
"fn __T_h(n, w, ctx):\n"
"    lv = n.p[\"level\"]\n"
"    lines = __wrap(n.p[\"text\"], w)\n"
"    if lv == 1:\n"
"        return [__fg(\"accent\", l, True) for l in lines]\n"
"    return [__bold(l) for l in lines]\n"
"\n"
"fn __T_code(n, w, ctx):\n"
"    if n.p[\"block\"]:\n"
"        return [__dim(\"  \" + l) for l in n.p[\"text\"].split(\"\\n\")]\n"
"    return [__fg(\"teal\", n.p[\"text\"])]\n"
"\n"
"fn __T_link(n, w, ctx):\n"
"    f = __tfocus(ctx, {\"kind\": \"link\", \"to\": n.p[\"to\"]})\n"
"    s = (__glyph(n.p[\"icon\"]) + \" \" if n.p[\"icon\"] != Nil else \"\") + n.p[\"text\"]\n"
"    return [__mark(f, __sgr(\"7\", s) if f else __sgr(\"4;38;5;\" + str(__hex256(\"accent\")), s))]\n"
"\n"
"fn __T_bullets(n, w, ctx):\n"
"    out = []\n"
"    for k in n.kids:\n"
"        b = __trender(k, w - 2, ctx)\n"
"        for i in range(len(b)):\n"
"            out.append((__fg(\"accent\", \"•\") + \" \" if i == 0 else \"  \") + b[i])\n"
"    return out\n"
"\n"
"fn __tcell(v, ctx):\n"
"    if isinstance(v, El):\n"
"        b = __trender(v, 200, ctx)\n"
"        return b[-1] if len(b) > 0 else \"\"\n"
"    if v == Nil:\n"
"        return __dim(\"—\")\n"
"    return str(v)\n"
"\n"
"fn __T_kv(n, w, ctx):\n"
"    d = n.p[\"data\"]\n"
"    kw = 0\n"
"    for k in d:\n"
"        if len(__label(k)) > kw:\n"
"            kw = len(__label(k))\n"
"    return [__dim(__label(k).ljust(kw)) + \"  \" + __tcell(d[k], ctx) for k in d]\n"
"\n"
"fn __T_html(n, w, ctx):\n"
"    return [__dim(\"[html]\")]\n"
"\n"
"fn __T_el(n, w, ctx):\n"
"    return __T_kids(n.kids, w, ctx)\n"
"\n"
"fn __T_badge(n, w, ctx):\n"
"    return [__sgr(\"1;38;5;\" + str(__hex256(n.p[\"color\"])), \"‹\" + n.p[\"text\"] + \"›\")]\n"
"\n"
"fn __T_avatar(n, w, ctx):\n"
"    return [__sgr(\"1;38;5;\" + str(16 + 36 * 2 + 6 * (__hue(n.p[\"name\"]) % 4 + 1) + 5), \"(\" + __initials(n.p[\"name\"]) + \")\")]\n"
"\n"
"fn __T_image(n, w, ctx):\n"
"    return [__dim(\"[image\" + (\": \" + str(n.p[\"alt\"]) if n.p[\"alt\"] != \"\" else \"\") + \"]\")]\n"
"\n"
"fn __T_icon(n, w, ctx):\n"
"    g = __glyph(n.p[\"name\"])\n"
"    return [__fg(n.p[\"color\"], g) if n.p[\"color\"] != Nil else g]\n"
"\n"
"fn __T_stat(n, w, ctx):\n"
"    p = n.p\n"
"    body = [__dim(p[\"label\"]) + ((\" \" + __fg(\"accent\", __glyph(p[\"icon\"]))) if p[\"icon\"] != Nil else \"\"), __bold(p[\"value\"])]\n"
"    foot = \"\"\n"
"    if p[\"delta\"] != Nil:\n"
"        d = str(p[\"delta\"])\n"
"        down = d.startswith(\"-\")\n"
"        foot = __fg(\"red\" if down else \"green\", (\"▼ \" if down else \"▲ \") + d.lstrip(\"+-\"))\n"
"    if p[\"hint\"] != Nil:\n"
"        foot += (\" \" if foot != \"\" else \"\") + __dim(p[\"hint\"])\n"
"    if foot != \"\":\n"
"        body.append(foot)\n"
"    return __box(body, w if w < 40 else 40)\n"
"\n"
"fn __T_progress(n, w, ctx):\n"
"    pct = __pct(n.p[\"value\"], n.p[\"max\"])\n"
"    label = str(round(pct)) + \"%\"\n"
"    out = []\n"
"    if n.p[\"label\"] != Nil:\n"
"        out.append(__padr(str(n.p[\"label\"]), w - len(label)) + __dim(label))\n"
"    bw = w if n.p[\"label\"] != Nil else w - len(label) - 1\n"
"    filled = int(bw * pct / 100)\n"
"    bar = __fg(n.p[\"color\"], \"█\" * filled) + __dim(\"░\" * (bw - filled))\n"
"    out.append(bar if n.p[\"label\"] != Nil else bar + \" \" + __dim(label))\n"
"    return out\n"
"\n"
"fn __T_table(n, w, ctx):\n"
"    rows = n.p[\"rows\"]\n"
"    cols = __columns(rows, n.p[\"columns\"])\n"
"    cells = []\n"
"    for r in rows:\n"
"        if typename(r) == \"dict\":\n"
"            cells.append([__tcell(r.get(c), ctx) for c in cols])\n"
"        else:\n"
"            cells.append([__tcell(v, ctx) for v in r])\n"
"    ncol = len(cols) if cols != Nil else (len(cells[0]) if len(cells) > 0 else 0)\n"
"    if ncol == 0:\n"
"        return []\n"
"    widths = [len(__label(c)) for c in cols] if cols != Nil else [0] * ncol\n"
"    for r in cells:\n"
"        for i in range(ncol):\n"
"            if i < len(r) and __vlen(r[i]) > widths[i]:\n"
"                widths[i] = __vlen(r[i])\n"
"    # Shrink the widest columns until the table fits.\n"
"    while sum(widths) + 2 * (ncol - 1) > w:\n"
"        big = 0\n"
"        for i in range(ncol):\n"
"            if widths[i] > widths[big]:\n"
"                big = i\n"
"        if widths[big] <= 4:\n"
"            break\n"
"        widths[big] -= 1\n"
"    out = []\n"
"    if cols != Nil:\n"
"        out.append(\"  \".join([__dim(__padr(__label(cols[i]).upper(), widths[i])[:widths[i]]) for i in range(ncol)]))\n"
"        out.append(__dim(\"─\" * (sum(widths) + 2 * (ncol - 1))))\n"
"    for r in cells:\n"
"        out.append(\"  \".join([__padr(__cut(r[i] if i < len(r) else \"\", widths[i]), widths[i]) for i in range(ncol)]))\n"
"    return out\n"
"\n"
"fn __T_alert(n, w, ctx):\n"
"    kind = n.p[\"kind\"]\n"
"    color = \"green\" if kind == \"success\" else \"amber\" if kind == \"warning\" else \"red\" if kind == \"error\" or kind == \"danger\" else \"blue\"\n"
"    bar = __fg(color, \"▌\")\n"
"    out = []\n"
"    if n.p[\"title\"] != Nil:\n"
"        out.append(bar + \" \" + __fg(color, __glyph(__kind_icon(kind)), True) + \" \" + __bold(n.p[\"title\"]))\n"
"    lines = __wrap(n.p[\"text\"], w - 2)\n"
"    for i in range(len(lines)):\n"
"        prefix = __fg(color, __glyph(__kind_icon(kind))) + \" \" if n.p[\"title\"] == Nil and i == 0 else \"\"\n"
"        out.append(bar + \" \" + prefix + lines[i])\n"
"    return out\n"
"\n"
"fn __T_empty(n, w, ctx):\n"
"    out = [__dim(__glyph(n.p[\"icon\"])), __bold(n.p[\"title\"])]\n"
"    if n.p[\"text\"] != Nil:\n"
"        out += [__dim(l) for l in __wrap(n.p[\"text\"], w)]\n"
"    out += __T_kids(n.kids, w, ctx)\n"
"    return [\" \" * ((w - __vlen(l)) // 2) + l for l in out]\n"
"\n"
"fn __T_spinner(n, w, ctx):\n"
"    return [__fg(\"accent\", \"⠿\") + \" \" + __dim(n.p[\"text\"] if n.p[\"text\"] != Nil else \"loading\")]\n"
"\n"
"fn __T_button(n, w, ctx):\n"
"    p = n.p\n"
"    f = __tfocus(ctx, {\"kind\": \"button\", \"on\": p[\"on\"], \"disabled\": p[\"disabled\"]})\n"
"    label = ((__glyph(p[\"icon\"]) + \" \") if p[\"icon\"] != Nil else \"\") + p[\"text\"]\n"
"    label = label.strip()\n"
"    if f:\n"
"        s = __sgr(\"1;7\", \" \" + label + \" \")\n"
"    elif p[\"disabled\"]:\n"
"        s = __dim(\"[ \" + label + \" ]\")\n"
"    elif p[\"variant\"] == \"primary\":\n"
"        s = __fg(\"accent\", \"[ \" + label + \" ]\", True)\n"
"    elif p[\"variant\"] == \"danger\":\n"
"        s = __fg(\"red\", \"[ \" + label + \" ]\", True)\n"
"    elif p[\"variant\"] == \"ghost\":\n"
"        s = \" \" + label + \" \"\n"
"    else:\n"
"        s = \"[ \" + label + \" ]\"\n"
"    return [__mark(f, s)]\n"
"\n"
"fn __T_field(label, value, placeholder, w, f, multiline):\n"
"    out = []\n"
"    if label != Nil:\n"
"        out.append(__dim(label))\n"
"    fw = w if w < 48 else 48\n"
"    shown = value if value != \"\" else placeholder\n"
"    lines = __wrap(shown, fw - 2) if multiline else [shown[-(fw - 2):] if len(shown) > fw - 2 else shown]\n"
"    for i in range(len(lines)):\n"
"        l = lines[i]\n"
"        text = l if value != \"\" else __dim(l)\n"
"        if f and i == len(lines) - 1:\n"
"            text = (l if value != \"\" else \"\") + __sgr(\"7\", \" \")\n"
"        out.append(__mark(f and i == 0, \"  \" + text))\n"
"    out.append(__fg(\"accent\", \"─\" * fw) if f else __dim(\"─\" * fw))\n"
"    return out\n"
"\n"
"fn __T_input(n, w, ctx):\n"
"    p = n.p\n"
"    f = __tfocus(ctx, {\"kind\": \"input\", \"bind\": p[\"bind\"], \"submit\": p[\"on_submit\"], \"multi\": False})\n"
"    v = __val(p[\"bind\"])\n"
"    if p[\"type\"] == \"password\":\n"
"        v = \"•\" * len(v)\n"
"    return __T_field(p[\"label\"], v, p[\"placeholder\"], w, f, False)\n"
"\n"
"fn __T_textarea(n, w, ctx):\n"
"    p = n.p\n"
"    f = __tfocus(ctx, {\"kind\": \"input\", \"bind\": p[\"bind\"], \"submit\": Nil, \"multi\": True})\n"
"    return __T_field(p[\"label\"], __val(p[\"bind\"]), p[\"placeholder\"], w, f, True)\n"
"\n"
"fn __T_checkbox(n, w, ctx):\n"
"    p = n.p\n"
"    f = __tfocus(ctx, {\"kind\": \"check\", \"bind\": p[\"bind\"], \"on\": p[\"on\"], \"checked\": p[\"checked\"]})\n"
"    on = __checked(p)\n"
"    box = __fg(\"accent\", \"☑\") if on else \"☐\"\n"
"    label = __sgr(\"7\", p[\"text\"]) if f else p[\"text\"]\n"
"    return [__mark(f, box + \" \" + label)]\n"
"\n"
"fn __T_switch(n, w, ctx):\n"
"    p = n.p\n"
"    f = __tfocus(ctx, {\"kind\": \"check\", \"bind\": p[\"bind\"], \"on\": p[\"on\"], \"checked\": p[\"checked\"]})\n"
"    on = __checked(p)\n"
"    sw = __fg(\"accent\", \"━●\", True) if on else __dim(\"○━\")\n"
"    label = __sgr(\"7\", p[\"text\"]) if f else p[\"text\"]\n"
"    return [__mark(f, sw + \" \" + label + \"  \" + (__fg(\"accent\", \"on\") if on else __dim(\"off\")))]\n"
"\n"
"fn __T_select(n, w, ctx):\n"
"    p = n.p\n"
"    f = __tfocus(ctx, {\"kind\": \"select\", \"bind\": p[\"bind\"], \"options\": p[\"options\"], \"on\": p[\"on\"]})\n"
"    cur = __val(p[\"bind\"])\n"
"    shown = cur\n"
"    for o in p[\"options\"]:\n"
"        v, l = __option(o)\n"
"        if v == cur:\n"
"            shown = l\n"
"    s = \"‹ \" + shown + \" ›\"\n"
"    out = []\n"
"    if p[\"label\"] != Nil:\n"
"        out.append(__dim(p[\"label\"]))\n"
"    out.append(__mark(f, __sgr(\"7\", s) if f else __fg(\"accent\", s)))\n"
"    return out\n"
"\n"
"fn __T_slider(n, w, ctx):\n"
"    p = n.p\n"
"    f = __tfocus(ctx, {\"kind\": \"slider\", \"bind\": p[\"bind\"], \"min\": p[\"min\"], \"max\": p[\"max\"], \"step\": p[\"step\"], \"on\": p[\"on\"]})\n"
"    v = p[\"bind\"].value if p[\"bind\"] != Nil else p[\"min\"]\n"
"    bw = (w if w < 40 else 40) - 1\n"
"    pos = int(bw * __pct(v - p[\"min\"], p[\"max\"] - p[\"min\"]) / 100)\n"
"    bar = __fg(\"accent\", \"━\" * pos) + (__sgr(\"7\", \"●\") if f else __fg(\"accent\", \"●\", True)) + __dim(\"┄\" * (bw - pos))\n"
"    out = []\n"
"    if p[\"label\"] != Nil:\n"
"        out.append(__padr(__dim(p[\"label\"]), bw - len(str(v)) + 1) + __bold(str(v)))\n"
"    out.append(__mark(f, bar))\n"
"    return out\n"
"\n"
"fn __T_tabs(n, w, ctx):\n"
"    b = n.p[\"bind\"]\n"
"    f = __tfocus(ctx, {\"kind\": \"tabs\", \"bind\": b, \"options\": n.p[\"options\"], \"on\": n.p[\"on\"]})\n"
"    parts = []\n"
"    for o in n.p[\"options\"]:\n"
"        v, l = __option(o)\n"
"        active = b != Nil and str(b.value) == v\n"
"        if active:\n"
"            parts.append(__sgr(\"1;7\", \" \" + l + \" \") if f else __sgr(\"1;4;38;5;\" + str(__hex256(\"accent\")), \" \" + l + \" \"))\n"
"        else:\n"
"            parts.append(__dim(\" \" + l + \" \"))\n"
"    return [__mark(f, \"\".join(parts))]\n"
"\n"
"fn __tbrand(brand):\n"
"    return __fg(\"accent\", \"◆ \" + (str(brand) if not isinstance(brand, El) else \"App\"), True)\n"
"\n"
"fn __T_navbar(n, w, ctx):\n"
"    items = []\n"
"    for k in n.kids:\n"
"        b = __trender(k, w, ctx)\n"
"        if len(b) > 0:\n"
"            items.append(b[0])\n"
"    line = __tbrand(n.p[\"brand\"]) + \"   \" + \"  \".join(items)\n"
"    return [line, __dim(\"─\" * w)]\n"
"\n"
"fn __T_nav(n, w, ctx):\n"
"    active = __ui[\"path\"] == n.p[\"to\"]\n"
"    f = __tfocus(ctx, {\"kind\": \"link\", \"to\": n.p[\"to\"]})\n"
"    s = ((__glyph(n.p[\"icon\"]) + \" \") if n.p[\"icon\"] != Nil else \"\") + n.p[\"text\"]\n"
"    if f:\n"
"        s = __sgr(\"7\", \" \" + s + \" \")\n"
"    elif active:\n"
"        s = __fg(\"accent\", \" \" + s + \" \", True)\n"
"    else:\n"
"        s = \" \" + s + \" \"\n"
"    return [__mark(f, s)]\n"
"\n"
"fn __T_sidebar(n, w, ctx):\n"
"    out = [__tbrand(n.p[\"brand\"]), \"\"]\n"
"    for k in n.kids:\n"
"        out += __trender(k, w, ctx)\n"
"    return out\n"
"\n"
"fn __T_shell(n, w, ctx):\n"
"    chrome = n.p[\"chrome\"]\n"
"    if chrome != Nil and chrome.t == \"sidebar\" and w >= 72:\n"
"        sw = 22\n"
"        side = __T_sidebar(chrome, sw - 2, ctx)\n"
"        body = __T_kids(n.kids, w - sw - 1, ctx)\n"
"        rows = len(side) if len(side) > len(body) else len(body)\n"
"        out = []\n"
"        for i in range(rows):\n"
"            l = side[i] if i < len(side) else \"\"\n"
"            r = body[i] if i < len(body) else \"\"\n"
"            out.append(__padr(l, sw - 1) + __dim(\"│\") + \" \" + r)\n"
"        return out\n"
"    out = []\n"
"    if chrome != Nil:\n"
"        if chrome.t == \"sidebar\":\n"
"            out = __T_navbar(El(\"navbar\", chrome.kids, {\"brand\": chrome.p[\"brand\"]}), w, ctx)\n"
"        else:\n"
"            out = __T_navbar(chrome, w, ctx)\n"
"        out.append(\"\")\n"
"    return out + __T_kids(n.kids, w, ctx)\n"
"\n"
"# An open modal takes over the screen (see __term_frame).\n"
"fn __T_modal(n, w, ctx):\n"
"    b = n.p[\"bind\"]\n"
"    if b != Nil and b.value and ctx.get(\"modal\") == Nil:\n"
"        ctx[\"modal\"] = n\n"
"    return []\n"
"\n"
"__T = {\n"
"    \"col\": __T_col, \"row\": __T_row, \"grid\": __T_grid, \"center\": __T_center,\n"
"    \"card\": __T_card, \"section\": __T_section, \"spacer\": __T_spacer,\n"
"    \"divider\": __T_divider, \"text\": __T_text, \"h\": __T_h, \"code\": __T_code,\n"
"    \"link\": __T_link, \"bullets\": __T_bullets, \"kv\": __T_kv, \"html\": __T_html,\n"
"    \"el\": __T_el, \"badge\": __T_badge, \"avatar\": __T_avatar, \"image\": __T_image,\n"
"    \"icon\": __T_icon, \"stat\": __T_stat, \"progress\": __T_progress,\n"
"    \"table\": __T_table, \"alert\": __T_alert, \"empty\": __T_empty,\n"
"    \"spinner\": __T_spinner, \"button\": __T_button, \"input\": __T_input,\n"
"    \"textarea\": __T_textarea, \"checkbox\": __T_checkbox, \"switch\": __T_switch,\n"
"    \"select\": __T_select, \"slider\": __T_slider, \"tabs\": __T_tabs,\n"
"    \"navbar\": __T_navbar, \"sidebar\": __T_sidebar, \"nav\": __T_nav,\n"
"    \"shell\": __T_shell, \"modal\": __T_modal,\n"
"}\n"
"\n"
"# Lay out the view at `path` for a w-column terminal: (lines, ctx).\n"
"fn __term_frame(path, w):\n"
"    node = __view(path)\n"
"    ctx = {\"focus\": [], \"modal\": Nil}\n"
"    lines = __trender(node, w, ctx)\n"
"    m = ctx[\"modal\"]\n"
"    if m != Nil:\n"
"        # Only the dialog is interactive while it's open.\n"
"        ctx = {\"focus\": [], \"modal\": m}\n"
"        bw = w if w < 64 else 64\n"
"        body = __T_kids(m.kids, bw - 4, ctx)\n"
"        body += [\"\", __dim(\"esc to close\")]\n"
"        box = __box(body, bw, m.p[\"title\"], \"accent\")\n"
"        left = \" \" * ((w - bw) // 2)\n"
"        lines = [\"\", \"\"] + [left + l for l in box]\n"
"    return (lines, ctx)\n"
"\n"
"# The view at `path` as plain text (no colors), e.g. for tests.\n"
"fn render_text(path=\"/\", width=80):\n"
"    __ui[\"plain\"] = True\n"
"    __ui[\"tfocus\"] = -1\n"
"    lines, ctx = __term_frame(path, width)\n"
"    __ui[\"plain\"] = False\n"
"    return \"\\n\".join([l.rstrip() for l in lines])\n"
"\n"
"fn __term_act(item, k, path):\n"
"    kind = item[\"kind\"]\n"
"    if kind == \"button\":\n"
"        if (k == \"enter\" or k == \" \") and item[\"on\"] != Nil and not item[\"disabled\"]:\n"
"            __run_task(item[\"on\"])\n"
"    elif kind == \"link\":\n"
"        if k == \"enter\" or k == \" \":\n"
"            return item[\"to\"]\n"
"    elif kind == \"check\":\n"
"        if k == \"enter\" or k == \" \":\n"
"            if item[\"bind\"] != Nil:\n"
"                item[\"bind\"].toggle()\n"
"            if item[\"on\"] != Nil:\n"
"                __run_task(item[\"on\"])\n"
"    elif kind == \"select\":\n"
"        opts = [__option(o)[0] for o in item[\"options\"]]\n"
"        if len(opts) > 0 and (k == \"left\" or k == \"right\" or k == \"enter\" or k == \" \"):\n"
"            b = item[\"bind\"]\n"
"            cur = __val(b)\n"
"            i = opts.index(cur) if cur in opts else -1\n"
"            i = (i - 1 if k == \"left\" else i + 1) % len(opts)\n"
"            if b != Nil:\n"
"                b.set(opts[i])\n"
"            if item[\"on\"] != Nil:\n"
"                __run_task(item[\"on\"])\n"
"    elif kind == \"slider\":\n"
"        b = item[\"bind\"]\n"
"        steps = {\"left\": -1, \"right\": 1, \"pagedown\": -10, \"pageup\": 10, \"home\": -1000000, \"end\": 1000000}\n"
"        if b != Nil and k in steps:\n"
"            v = b.value + steps[k] * item[\"step\"]\n"
"            v = item[\"min\"] if v < item[\"min\"] else item[\"max\"] if v > item[\"max\"] else v\n"
"            b.set(v)\n"
"            if item[\"on\"] != Nil:\n"
"                __run_task(item[\"on\"])\n"
"    elif kind == \"tabs\":\n"
"        b = item[\"bind\"]\n"
"        opts = [__option(o)[0] for o in item[\"options\"]]\n"
"        if b != Nil and len(opts) > 0 and (k == \"left\" or k == \"right\"):\n"
"            i = opts.index(str(b.value)) if str(b.value) in opts else 0\n"
"            i = (i - 1 if k == \"left\" else i + 1) % len(opts)\n"
"            __run_task((__tab, b, opts[i], item[\"on\"]))\n"
"    elif kind == \"input\":\n"
"        b = item[\"bind\"]\n"
"        if b == Nil:\n"
"            return Nil\n"
"        v = __val(b)\n"
"        if k == \"backspace\":\n"
"            b.set(v[:-1])\n"
"        elif k == \"enter\":\n"
"            if item[\"multi\"]:\n"
"                b.set(v + \"\\n\")\n"
"            elif item[\"submit\"] != Nil:\n"
"                __run_task(item[\"submit\"])\n"
"        elif len(k) == 1:\n"
"            b.set(v + k)\n"
"    return Nil\n"
"\n"
"fn __term_run():\n"
"    if not isatty():\n"
"        print(render_text(\"/\"))\n"
"        return Nil\n"
"    path = \"/\"\n"
"    scroll = 0\n"
"    toast_until = 0\n"
"    toast_text = \"\"\n"
"    __traw(True)\n"
"    __twrite(\"\\x1b[?1049h\\x1b[?25l\")\n"
"    try:\n"
"        while True:\n"
"            cols, rows = __tsize()\n"
"            w = cols - 4 if cols > 104 else cols - 2\n"
"            w = 100 if w > 100 else w\n"
"            lines, ctx = __term_frame(path, w)\n"
"            nf = len(ctx[\"focus\"])\n"
"            if __ui[\"tfocus\"] >= nf:\n"
"                __ui[\"tfocus\"] = nf - 1 if nf > 0 else 0\n"
"                lines, ctx = __term_frame(path, w)\n"
"            # Keep the focused line on screen.\n"
"            fline = 0\n"
"            for i in range(len(lines)):\n"
"                if \"\\x01\" in lines[i]:\n"
"                    fline = i\n"
"                    lines[i] = lines[i].replace(\"\\x01\", \"\")\n"
"            height = rows - 2\n"
"            if fline < scroll:\n"
"                scroll = fline\n"
"            elif fline >= scroll + height:\n"
"                scroll = fline - height + 1\n"
"            if scroll > len(lines) - height:\n"
"                scroll = len(lines) - height if len(lines) > height else 0\n"
"            for t in __take_toasts():\n"
"                toast_text = (__fg(\"red\", \"✕ \") if t[\"kind\"] == \"error\" else __fg(\"green\", \"✓ \")) + t[\"text\"]\n"
"                toast_until = monotonic() + 3\n"
"            status = toast_text if monotonic() < toast_until else __dim(\"↑↓ move · enter select · ←→ change · esc quit\")\n"
"            margin = \" \" * ((cols - w) // 2)\n"
"            screen = [\"\\x1b[H\"]\n"
"            view = lines[scroll:scroll + height]\n"
"            screen.append(\"\\r\\n\")\n"
"            for l in view:\n"
"                screen.append(\"\\x1b[2K\" + margin + __cut(l, w) + \"\\r\\n\")\n"
"            for i in range(height - len(view)):\n"
"                screen.append(\"\\x1b[2K\\r\\n\")\n"
"            screen.append(\"\\x1b[2K\" + margin + __cut(status, w))\n"
"            __twrite(\"\".join(screen))\n"
"            # Wait for a key, but wake up for background tasks and timers.\n"
"            due = __next_due()\n"
"            wait = -1 if due < 0 else int(due * 1000) + 1\n"
"            if len(__ui[\"waiting\"]) > 0:\n"
"                wait = 30 if wait < 0 or wait > 30 else wait\n"
"            if monotonic() < toast_until:\n"
"                wait = 500 if wait < 0 or wait > 500 else wait\n"
"            k = __tkey(wait)\n"
"            tasks = __pending_fds()\n"
"            __wake(__tready(tasks, 0) if len(tasks) > 0 else [])\n"
"            if k == Nil:\n"
"                continue\n"
"            if k == \"ctrl-c\":\n"
"                return Nil\n"
"            if k == \"esc\":\n"
"                if ctx[\"modal\"] != Nil:\n"
"                    ctx[\"modal\"].p[\"bind\"].set(False)\n"
"                    __ui[\"tfocus\"] = 0\n"
"                    continue\n"
"                return Nil\n"
"            item = ctx[\"focus\"][__ui[\"tfocus\"]] if nf > 0 else Nil\n"
"            typing = item != Nil and item[\"kind\"] == \"input\"\n"
"            if k == \"q\" and not typing:\n"
"                return Nil\n"
"            if k == \"down\" or k == \"tab\":\n"
"                __ui[\"tfocus\"] = (__ui[\"tfocus\"] + 1) % nf if nf > 0 else 0\n"
"                continue\n"
"            if k == \"up\" or k == \"shift-tab\":\n"
"                __ui[\"tfocus\"] = (__ui[\"tfocus\"] - 1) % nf if nf > 0 else 0\n"
"                continue\n"
"            if item == Nil:\n"
"                continue\n"
"            go_to = Nil\n"
"            try:\n"
"                go_to = __term_act(item, k, path)\n"
"            catch e:\n"
"                toast(str(e), \"error\")\n"
"            __ui[\"version\"] += 1\n"
"            if __ui[\"go\"] != Nil:\n"
"                go_to = __ui[\"go\"]\n"
"                __ui[\"go\"] = Nil\n"
"            if go_to != Nil and go_to != path:\n"
"                if go_to.startswith(\"http\"):\n"
"                    __open_browser(go_to)\n"
"                else:\n"
"                    path = go_to\n"
"                    __ui[\"tfocus\"] = 0\n"
"                    scroll = 0\n"
"    final:\n"
"        __twrite(\"\\x1b[0m\\x1b[?25h\\x1b[?1049l\")\n"
"        __traw(False)\n"
;

static const struct { const char *name; const char *src; } stdlib_modules[] = {
    {"http", STDLIB_SRC_http},
    {"mono", STDLIB_SRC_mono},
    {"newapp", STDLIB_SRC_newapp},
    {"strutil", STDLIB_SRC_strutil},
    {"ui", STDLIB_SRC_ui},
    {NULL, NULL}
};

// Returns the embedded source for `name`, or NULL if not a stdlib
// module. Linear scan — fine for the handful of stdlib modules we
// have. Swap for a perfect hash if/when that ever matters.
static inline const char *stdlib_source_lookup(const char *name)
{
    if (name == NULL) return NULL;
    for (int i = 0; stdlib_modules[i].name != NULL; i++)
    {
        if (strcmp(stdlib_modules[i].name, name) == 0)
            return stdlib_modules[i].src;
    }
    return NULL;
}

#endif
